"use client";

/**
 * Ticket. A paper pass: what it's for on the main part, the code on a stub
 * across a perforation. Use it and the stub tears off along the perforation
 * and drops away, leaving the torn edge and "Used" where it was. For event
 * tickets, boarding passes, coupons, invites and gift cards.
 *
 * Same paper and ink as Receipt. Everything printed is text in the page, the
 * details a description list; the barcode is a picture of its code, printed
 * beneath it. Tearing it has a button.
 */
import { useId, useState, type ReactNode } from "react";
import { useReducedMotionRef } from "echo-ui-core/tactile";
import { useSoundOptional } from "echo-ui-core/sound";
import { HardwareButton } from "../hardware-button";
import { barcode } from "../receipt/barcode";
import "./ticket.css";

export interface TicketDetail {
  label: string;
  value: ReactNode;
}

export interface TicketProps {
  /** What it's for, printed large, and the ticket's heading. */
  title: string;
  /** Where, or who it's from. */
  subtitle?: string;
  /** The facts on the main part: a date, a door, a seat. */
  details?: readonly TicketDetail[];
  /** The code on the stub, as a barcode and in text. */
  code: string;
  /** Printed on the stub over its code: "Admit one", "Boarding". */
  stubLabel?: string;
  /** Torn off (controlled). */
  used?: boolean;
  defaultUsed?: boolean;
  /** Called once the stub has dropped away. With it, the ticket shows a key to use it. */
  onUse?: () => void;
  /** The key's word. Default "Use ticket". */
  useLabel?: string;
  /** The heading's level. Default 3. */
  headingLevel?: 2 | 3 | 4;
}

export function Ticket({
  title,
  subtitle,
  details = [],
  code,
  stubLabel,
  used,
  defaultUsed = false,
  onUse,
  useLabel = "Use ticket",
  headingLevel = 3,
}: TicketProps) {
  const Heading = `h${headingLevel}` as const;
  const id = useId();
  const sound = useSoundOptional();
  const reduced = useReducedMotionRef();
  const [inner, setInner] = useState(defaultUsed);
  const [tearing, setTearing] = useState(false);
  const isUsed = used ?? inner;
  const use = () => {
    if (isUsed || tearing) return;
    sound?.play("release");
    setTearing(true);
    window.setTimeout(
      () => {
        setTearing(false);
        if (used === undefined) setInner(true);
        onUse?.();
      },
      reduced.current ? 0 : 520,
    );
  };
  return (
    <section className="echo-ticket" aria-labelledby={`${id}-title`} data-used={isUsed || undefined} data-tearing={tearing || undefined}>
      <div className="echo-ticket__paper">
        <div className="echo-ticket__main">
          <Heading id={`${id}-title`} className="echo-ticket__title">
            {title}
          </Heading>
          {subtitle ? <p className="echo-ticket__subtitle">{subtitle}</p> : null}
          {details.length ? (
            <dl className="echo-ticket__details">
              {details.map((d) => (
                <div key={d.label} className="echo-ticket__detail">
                  <dt>{d.label}</dt>
                  <dd>{d.value}</dd>
                </div>
              ))}
            </dl>
          ) : null}
        </div>
        <div className="echo-ticket__perforation" aria-hidden="true" />
        <div className="echo-ticket__stub">
          {isUsed ? (
            <p className="echo-ticket__used">Used</p>
          ) : (
            <>
              {stubLabel ? <p className="echo-ticket__stub-label">{stubLabel}</p> : null}
              <svg className="echo-ticket__barcode" viewBox="0 0 200 36" preserveAspectRatio="none" aria-hidden="true" focusable="false">
                {barcode(code).map((bar, i) => (
                  <rect key={i} x={bar.x} y={0} width={bar.w} height={36} />
                ))}
              </svg>
              <p className="echo-ticket__code">{code}</p>
            </>
          )}
        </div>
      </div>
      {onUse && !isUsed ? (
        <div className="echo-ticket__action">
          <HardwareButton size="sm" disabled={tearing} onClick={use}>
            {useLabel}
          </HardwareButton>
        </div>
      ) : null}
    </section>
  );
}

/**
 * Ticket. Receipt's paper and ink: the main part and a stub across a
 * perforation, notched at both ends. Used, the stub has torn away along it.
 * Composes var(--echo-*) — no hex literals; the only fixed values are the key
 * light.
 */
.echo-ticket {
  container-type: inline-size;
  display: grid;
  gap: var(--echo-space-6);
  justify-items: start;
  inline-size: min(100%, 520px);
  min-inline-size: 0;
}

.echo-ticket__paper {
  --tk-notch: var(--echo-space-6, 12px);
  --tk-stub: 34%;
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 0 var(--tk-stub);
  inline-size: 100%;
  color: var(--echo-paper-ink, var(--echo-surface));
  background: var(--echo-paper-stock, var(--echo-text));
  border-radius: var(--echo-radius-lg);
  /* The two notches where the perforation meets the edges. */
  -webkit-mask:
    radial-gradient(circle var(--tk-notch) at calc(100% - var(--tk-stub)) 0, transparent 98%, var(--echo-seam)) top / 100% 51% no-repeat,
    radial-gradient(circle var(--tk-notch) at calc(100% - var(--tk-stub)) 100%, transparent 98%, var(--echo-seam)) bottom / 100% 51% no-repeat;
  mask:
    radial-gradient(circle var(--tk-notch) at calc(100% - var(--tk-stub)) 0, transparent 98%, var(--echo-seam)) top / 100% 51% no-repeat,
    radial-gradient(circle var(--tk-notch) at calc(100% - var(--tk-stub)) 100%, transparent 98%, var(--echo-seam)) bottom / 100% 51% no-repeat;
  filter: drop-shadow(0 8px 14px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.45 * var(--echo-shade, 1) * 100%), transparent));
}

.echo-ticket__main {
  display: grid;
  gap: var(--echo-space-3);
  align-content: start;
  padding-block: var(--echo-space-9);
  padding-inline: var(--echo-space-9) var(--echo-space-8);
  min-inline-size: 0;
}
.echo-ticket__title {
  margin: 0;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-lg);
  font-weight: var(--echo-weight-heavy, 800);
  letter-spacing: var(--echo-tracking-tight, -0.01em);
  line-height: var(--echo-leading-tight, 1.25);
  overflow-wrap: anywhere;
}
.echo-ticket__subtitle {
  margin: 0;
  font-family: var(--echo-font-sans, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
}
.echo-ticket__details {
  display: flex;
  flex-wrap: wrap;
  gap: var(--echo-space-4) var(--echo-space-9);
  margin: var(--echo-space-4) 0 0;
}
.echo-ticket__detail {
  display: grid;
  gap: var(--echo-space-1);
}
.echo-ticket__detail dt {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
}
.echo-ticket__detail dd {
  margin: 0;
  font-family: var(--echo-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-sm);
  font-weight: var(--echo-weight-bold, 700);
}

/* The perforation: a row of holes between the main part and the stub. */
.echo-ticket__perforation {
  position: relative;
  margin-block: var(--tk-notch);
  border-inline-start: var(--echo-border-thick, 2px) dashed color-mix(in oklab, var(--echo-surface) 35%, transparent);
}

.echo-ticket__stub {
  display: grid;
  align-content: center;
  justify-items: center;
  gap: var(--echo-space-2);
  padding: var(--echo-space-8) var(--echo-space-6);
  min-inline-size: 0;
  transition:
    translate var(--echo-duration-flood) var(--echo-ease-glide),
    rotate var(--echo-duration-flood) var(--echo-ease-glide),
    opacity var(--echo-duration-pop) ease;
}
.echo-ticket__stub-label,
.echo-ticket__code,
.echo-ticket__used {
  margin: 0;
  font-family: var(--echo-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--echo-text-2xs);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
  text-align: center;
}
.echo-ticket__barcode {
  display: block;
  inline-size: 100%;
  block-size: 40px;
  fill: var(--echo-surface);
}
.echo-ticket__used {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-md);
  font-weight: var(--echo-weight-heavy, 800);
  letter-spacing: var(--echo-tracking-widest, 0.25em);
  opacity: 0.55;
}
/* Tearing: the stub comes away along the perforation and drops. */
.echo-ticket[data-tearing] .echo-ticket__stub {
  translate: 24px 56px;
  rotate: 8deg;
  opacity: 0;
}
.echo-ticket[data-used] .echo-ticket__perforation {
  border-inline-start-style: solid;
  border-inline-start-color: color-mix(in oklab, var(--echo-paper-ink, var(--echo-surface)) 20%, transparent);
}

/* Narrow: the stub goes under the main part. */
@container (max-width: 360px) {
  .echo-ticket__paper {
    --tk-stub: 0;
    grid-template-columns: minmax(0, 1fr);
    -webkit-mask: none;
    mask: none;
  }
  .echo-ticket__perforation {
    margin-block: 0;
    margin-inline: var(--echo-space-6);
    border-inline-start: 0;
    border-block-start: var(--echo-border-thick, 2px) dashed color-mix(in oklab, var(--echo-surface) 35%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .echo-ticket__stub {
    transition: opacity var(--echo-duration-swap) linear;
  }
  .echo-ticket[data-tearing] .echo-ticket__stub {
    translate: none;
    rotate: none;
  }
}
@media (forced-colors: active) {
  .echo-ticket__paper {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
    -webkit-mask: none;
    mask: none;
    filter: none;
  }
  .echo-ticket__barcode {
    fill: CanvasText;
  }
}
